<script>
window.LabKit = window.LabKit || (() => {
  const NS = 'http://www.w3.org/2000/svg';
  const sum = a => a.reduce((s, v) => s + v, 0);
  const mean = a => sum(a) / a.length;
  const variance = (a, ddof = 0) => { const m = mean(a); return sum(a.map(v => (v - m) ** 2)) / (a.length - ddof); };
  const sd = (a, ddof = 0) => Math.sqrt(variance(a, ddof));
  // Percentil con interpolación lineal (convención de numpy.percentile por defecto).
  const quantile = (a, q) => {
    const s = [...a].sort((x, y) => x - y), pos = (s.length - 1) * q, lo = Math.floor(pos), hi = Math.ceil(pos);
    return s[lo] + (s[hi] - s[lo]) * (pos - lo);
  };
  const median = a => quantile(a, 0.5);
  const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
  const fmt = (v, d = 2) => (v === null || v === undefined || Number.isNaN(v)) ? '—'
    : Number(v).toLocaleString('es-MX', { minimumFractionDigits: d, maximumFractionDigits: d });
  // Generador pseudoaleatorio reproducible (mulberry32) y normal estándar (Box-Muller).
  const rng = seed => {
    let t = seed >>> 0;
    const u = () => { t += 0x6D2B79F5; let r = Math.imul(t ^ (t >>> 15), 1 | t); r ^= r + Math.imul(r ^ (r >>> 7), 61 | r); return ((r ^ (r >>> 14)) >>> 0) / 4294967296; };
    u.normal = () => { let a = 0, b = 0; while (a === 0) a = u(); while (b === 0) b = u(); return Math.sqrt(-2 * Math.log(a)) * Math.cos(2 * Math.PI * b); };
    return u;
  };
  const niceTicks = (lo, hi, n = 5) => {
    if (hi === lo) { hi = lo + 1; }
    const raw = (hi - lo) / n, mag = 10 ** Math.floor(Math.log10(raw)), f = raw / mag;
    const step = (f >= 5 ? 10 : f >= 2 ? 5 : f >= 1 ? 2 : 1) * mag;
    const out = [];
    for (let v = Math.ceil(lo / step - 1e-9) * step; v <= hi + 1e-9; v += step) out.push(Math.abs(v) < step * 1e-9 ? 0 : v);
    return out;
  };
  const el = (tag, attrs = {}, parent) => {
    const node = document.createElementNS(NS, tag);
    for (const [k, v] of Object.entries(attrs)) if (v !== undefined && v !== null) node.setAttribute(k, v);
    if (parent) parent.appendChild(node);
    return node;
  };
  // Graficador mínimo: escala lineal, ejes, rejilla y primitivas.
  function chart(svg, opts) {
    const W = opts.width || 480, H = opts.height || 300;
    const m = Object.assign({ top: 14, right: 14, bottom: 38, left: 48 }, opts.margin || {});
    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    svg.classList.add('plab-chart');
    svg.replaceChildren();
    const [x0, x1] = opts.x, [y0, y1] = opts.y;
    const iw = W - m.left - m.right, ih = H - m.top - m.bottom;
    const X = v => m.left + (v - x0) / (x1 - x0) * iw;
    const Y = v => m.top + ih - (v - y0) / (y1 - y0) * ih;
    const c = {
      svg, X, Y, W, H, m, iw, ih,
      invX: px => x0 + (px - m.left) / iw * (x1 - x0),
      invY: py => y0 + (m.top + ih - py) / ih * (y1 - y0),
      g: el('g', {}, svg),
      axes({ xTicks = 5, yTicks = 5, xLabel = '', yLabel = '', xFmt = v => fmt(v, Math.abs(v) < 10 && v % 1 ? 1 : 0), yFmt, grid = true, xCats } = {}) {
        const ax = el('g', {}, svg); svg.insertBefore(ax, c.g);
        const yf = yFmt || xFmt;
        if (yTicks) niceTicks(y0, y1, yTicks).forEach(t => {
          if (grid) el('line', { x1: m.left, x2: m.left + iw, y1: Y(t), y2: Y(t), class: 'grid' }, ax);
          el('text', { x: m.left - 6, y: Y(t) + 3.5, 'text-anchor': 'end' }, ax).textContent = yf(t);
        });
        if (xCats) xCats.forEach(([v, lab]) => { el('text', { x: X(v), y: m.top + ih + 16, 'text-anchor': 'middle' }, ax).textContent = lab; });
        else if (xTicks) niceTicks(x0, x1, xTicks).forEach(t => {
          if (grid) el('line', { x1: X(t), x2: X(t), y1: m.top, y2: m.top + ih, class: 'grid' }, ax);
          el('text', { x: X(t), y: m.top + ih + 16, 'text-anchor': 'middle' }, ax).textContent = xFmt(t);
        });
        el('line', { x1: m.left, x2: m.left + iw, y1: m.top + ih, y2: m.top + ih, class: 'axis' }, ax);
        el('line', { x1: m.left, x2: m.left, y1: m.top, y2: m.top + ih, class: 'axis' }, ax);
        if (xLabel) el('text', { x: m.left + iw / 2, y: H - 4, 'text-anchor': 'middle', class: 'strong' }, ax).textContent = xLabel;
        if (yLabel) el('text', { x: 12, y: m.top + ih / 2, 'text-anchor': 'middle', transform: `rotate(-90 12 ${m.top + ih / 2})`, class: 'strong' }, ax).textContent = yLabel;
        return c;
      },
      zeroLines() {
        if (x0 < 0 && x1 > 0) el('line', { x1: X(0), x2: X(0), y1: m.top, y2: m.top + ih, class: 'zero' }, c.g);
        if (y0 < 0 && y1 > 0) el('line', { x1: m.left, x2: m.left + iw, y1: Y(0), y2: Y(0), class: 'zero' }, c.g);
        return c;
      },
      path(points, cls = 's1 line') {
        const d = points.filter(p => p && Number.isFinite(p[1])).map((p, i) => `${i ? 'L' : 'M'}${X(p[0]).toFixed(1)},${Y(p[1]).toFixed(1)}`).join('');
        return el('path', { d, class: cls }, c.g);
      },
      line(xa, ya, xb, yb, cls = 's1 line') { return el('line', { x1: X(xa), y1: Y(ya), x2: X(xb), y2: Y(yb), class: cls }, c.g); },
      dot(x, y, r = 5, cls = 's1 dot') { return el('circle', { cx: X(x), cy: Y(y), r, class: cls }, c.g); },
      rect(xa, ya, xb, yb, cls = 's1 soft') {
        return el('rect', { x: Math.min(X(xa), X(xb)), y: Math.min(Y(ya), Y(yb)), width: Math.abs(X(xb) - X(xa)), height: Math.abs(Y(yb) - Y(ya)), class: cls }, c.g);
      },
      text(x, y, s, attrs = {}) { const t = el('text', Object.assign({ x: X(x), y: Y(y) }, attrs), c.g); t.textContent = s; return t; },
      arrow(xa, ya, xb, yb, cls = 's1') {
        const ax = X(xa), ay = Y(ya), bx = X(xb), by = Y(yb), ang = Math.atan2(by - ay, bx - ax), h = 8;
        el('line', { x1: ax, y1: ay, x2: bx, y2: by, class: cls + ' line' }, c.g);
        el('path', { d: `M${bx},${by}L${bx - h * Math.cos(ang - 0.4)},${by - h * Math.sin(ang - 0.4)}L${bx - h * Math.cos(ang + 0.4)},${by - h * Math.sin(ang + 0.4)}Z`, class: cls }, c.g);
      },
      // Convierte un evento de puntero a coordenadas de datos.
      pointer(evt) {
        const pt = svg.createSVGPoint(); pt.x = evt.clientX; pt.y = evt.clientY;
        const p = pt.matrixTransform(svg.getScreenCTM().inverse());
        return [c.invX(p.x), c.invY(p.y)];
      }
    };
    svg.__chart = c;
    return c;
  }
  // Botones segmentados: devuelve un getter del valor activo.
  function segmented(container, onChange) {
    const buttons = [...container.querySelectorAll('button')];
    let value = (buttons.find(b => b.getAttribute('aria-pressed') === 'true') || buttons[0]).dataset.value;
    const set = v => { value = v; buttons.forEach(b => b.setAttribute('aria-pressed', String(b.dataset.value === v))); };
    set(value);
    buttons.forEach(b => b.addEventListener('click', () => { set(b.dataset.value); onChange && onChange(value); }));
    return { get: () => value, set: v => { set(v); onChange && onChange(value); } };
  }
  return { sum, mean, variance, sd, quantile, median, clamp, fmt, rng, niceTicks, el, chart, segmented };
})();
</script>
```
:::


Los árboles y los vecinos cercanos construyen fronteras flexibles a partir de reglas locales. Los **modelos lineales** hacen la apuesta contraria: resumen toda la información en un **puntaje** que es una suma ponderada de las variables,

$$
g(\mathbf{x}) = w_0 + w_1 x_1 + \cdots + w_p x_p = \mathbf{w}^\top\mathbf{x} + w_0,
$$

y deciden con ese puntaje. Para predecir un número, el puntaje es la predicción; para clasificar, basta mirar su **signo**. Su frontera de decisión es una recta en el plano y un hiperplano en general. Son menos flexibles que un árbol profundo, pero tienen poca varianza, se entrenan rápido, sus coeficientes se interpretan y son la base de la regresión logística, las máquinas de soporte vectorial y las redes neuronales.

Este capítulo recorre tres maneras de elegir $\mathbf{w}$: **mínimos cuadrados**, que ajusta números; el **discriminante de Fisher**, que busca la dirección que mejor separa dos clases; y el **perceptrón**, que corrige sus errores uno a uno. El capítulo siguiente presenta la cuarta y más usada, la regresión logística.

## Regresión lineal

### Intuición: la recta que menos se equivoca

Cinco estudiantes registraron sus horas de estudio $x$ y su calificación $y$ (sobre 10):

| Estudiante | 1 | 2 | 3 | 4 | 5 |
|---|---:|---:|---:|---:|---:|
| Horas $x$ | 1 | 2 | 3 | 4 | 5 |
| Calificación $y$ | 2 | 3 | 5 | 4 | 6 |

: Horas de estudio y calificación de cinco estudiantes. {#tbl-ols-datos}

Ninguna recta pasa por los cinco puntos. Para cada recta candidata $\hat{y} = \beta_0 + \beta_1 x$, cada estudiante tiene un **residuo** $e_i = y_i - \hat{y}_i$. El criterio de **mínimos cuadrados** [@legendre1805nouvelles; @gauss1809theoria] elige la recta que minimiza la suma de los residuos al cuadrado, $\text{SSE} = \sum_i e_i^2$. Elevar al cuadrado impide que errores positivos y negativos se cancelen y castiga más los errores grandes.

### Construcción paso a paso

**Paso 1. Centrar.** Las medias son $\bar{x} = 3$ y $\bar{y} = 20/5 = 4$.

**Paso 2. Pendiente.** Para una variable, la solución de mínimos cuadrados es el cociente entre la covariación de $x$ con $y$ y la variación de $x$:

| $x_i - \bar{x}$ | −2 | −1 | 0 | 1 | 2 | Suma |
|---|---:|---:|---:|---:|---:|---:|
| $y_i - \bar{y}$ | −2 | −1 | 1 | 0 | 2 | |
| $(x_i - \bar{x})(y_i - \bar{y})$ | 4 | 1 | 0 | 0 | 4 | $S_{xy} = 9$ |
| $(x_i - \bar{x})^2$ | 4 | 1 | 0 | 1 | 4 | $S_{xx} = 10$ |

: Cálculo de la pendiente. {#tbl-ols-pendiente}

$$
\hat{\beta}_1 = \frac{S_{xy}}{S_{xx}} = \frac{9}{10} = 0.9, \qquad \hat{\beta}_0 = \bar{y} - \hat{\beta}_1\bar{x} = 4 - 0.9 \cdot 3 = 1.3.
$$

Cada hora adicional de estudio se asocia con 0.9 puntos más de calificación.

**Paso 3. Predicciones y residuos.** Con $\hat{y} = 1.3 + 0.9x$:

| $x$ | 1 | 2 | 3 | 4 | 5 |
|---|---:|---:|---:|---:|---:|
| $\hat{y}$ | 2.2 | 3.1 | 4.0 | 4.9 | 5.8 |
| $e = y - \hat{y}$ | −0.2 | −0.1 | 1.0 | −0.9 | 0.2 |
| $e^2$ | 0.04 | 0.01 | 1.00 | 0.81 | 0.04 |

: Predicciones y residuos de la recta de mínimos cuadrados. {#tbl-ols-residuos}

**Paso 4. Métricas.** $\text{SSE} = 1.90$, de modo que el **error cuadrático medio** es $\text{MSE} = 1.90/5 = 0.38$ y su raíz $\text{RMSE} = 0.616$ puntos. El **error absoluto medio** es $\text{MAE} = (0.2 + 0.1 + 1.0 + 0.9 + 0.2)/5 = 0.48$. La variación total respecto a la media es $\text{SST} = \sum_i (y_i - \bar{y})^2 = 4 + 1 + 1 + 0 + 4 = 10$, así que

$$
R^2 = 1 - \frac{\text{SSE}}{\text{SST}} = 1 - \frac{1.9}{10} = 0.81:
$$

la recta explica el 81 % de la variación de las calificaciones respecto a predecir siempre el promedio.

### Formalización

Con $p$ variables, el modelo es $y_i = \beta_0 + \sum_j \beta_j x_{ij} + \varepsilon_i$. Apilando las observaciones en la **matriz de diseño** $\mathbf{X} \in \mathbb{R}^{n \times (p+1)}$, cuya primera columna es de unos, y en el vector $\mathbf{y}$, el problema es

$$
\hat{\boldsymbol{\beta}} = \arg\min_{\boldsymbol{\beta}} \|\mathbf{y} - \mathbf{X}\boldsymbol{\beta}\|^2.
$$ {#eq-ols}

Derivando e igualando a cero se obtienen las **ecuaciones normales** $\mathbf{X}^\top\mathbf{X}\hat{\boldsymbol{\beta}} = \mathbf{X}^\top\mathbf{y}$ y, si $\mathbf{X}^\top\mathbf{X}$ es invertible,

$$
\hat{\boldsymbol{\beta}} = (\mathbf{X}^\top\mathbf{X})^{-1}\mathbf{X}^\top\mathbf{y}.
$$ {#eq-ols-cerrada}

Geométricamente, $\hat{\mathbf{y}} = \mathbf{X}\hat{\boldsymbol{\beta}}$ es la **proyección ortogonal** de $\mathbf{y}$ sobre el espacio generado por las columnas de $\mathbf{X}$, y por eso los residuos son perpendiculares a cada columna: suman cero y no están correlacionados con ninguna variable. Si dos variables son (casi) linealmente dependientes, $\mathbf{X}^\top\mathbf{X}$ es (casi) singular y los coeficientes se vuelven inestables (**multicolinealidad**); la solución práctica es eliminar variables redundantes o **regularizar** sumando $\lambda\|\boldsymbol{\beta}\|^2$ a la pérdida (*ridge*) [@hoerl1970ridge], tema que se retoma con la regresión logística.

| Métrica | Fórmula | Unidades | Sensible a atípicos |
|---|---|---|---|
| MSE | $\frac{1}{n}\sum e_i^2$ | cuadrado de $y$ | mucho |
| RMSE | $\sqrt{\text{MSE}}$ | las de $y$ | mucho |
| MAE | $\frac{1}{n}\sum \lvert e_i \rvert$ | las de $y$ | poco |
| $R^2$ | $1 - \text{SSE}/\text{SST}$ | sin unidades | mucho |

: Métricas de regresión. {#tbl-metricas-regresion}

